B.aik=new A.bD("Ch\u01b0a t\u1ea3i \u0111\u01b0\u1ee3c h\xe0nh tr\xecnh \u0111\xe3 l\u01b0u.",B.Q,null)
B.ail=new A.bD("Gi\u01a1 camera v\u1ec1 ph\xeda hi\u1ec7n v\u1eadt t\u1ea1i t\u1ee7 tr\u01b0ng b\xe0y \u0111\u1ec3 ch\u1ee5p v\xe0 nh\u1eadn di\u1ec7n th\xf4ng minh, ho\u1eb7c t\u1ea3i \u1ea3nh c\xf3 s\u1eb5n t\u1eeb th\u01b0 vi\u1ec7n.",B.Q,null)
