B.ain=new A.bD("Xem hi\u1ec7n v\u1eadt n\u1eb1m \u1edf ph\xf2ng v\xe0 t\u1ea7ng n\xe0o. Qu\xe9t QR t\u1ea1i v\u1ecb tr\xed \u0111ang \u0111\u1ee9ng \u0111\u1ec3 t\xecm \u0111\u01b0\u1eddng tr\xean s\u01a1 \u0111\u1ed3.",B.Q,null)
B.aio=new A.bD("H\u1ecfi v\u1ec1 hi\u1ec7n v\u1eadt \u0111ang xem. Tr\u1ee3 l\xfd tham kh\u1ea3o n\u1ed9i dung ti\u1ebfng Vi\u1ec7t \u0111\xe3 \u0111\u01b0\u1ee3c b\u1ea3o t\xe0ng xu\u1ea5t b\u1ea3n.",B.Q,null)
B.aip=new A.bD("L\u01b0\u1ee3t tham quan t\u1ef1 do. Qu\xe9t QR t\u1ea1i hi\u1ec7n v\u1eadt \u0111\u1ec3 ghi nh\u1eadn kh\xe1m ph\xe1.",B.Q,null)
B.aiq=new A.bD("Ch\u01b0a c\xf3 n\u1ed9i dung c\u1ee7a g\xf3i.",B.Q,null)
B.air=new A.bD("C\xe0i \u0111\u1eb7t tr\u1ea3i nghi\u1ec7m n\xe0y \xe1p d\u1ee5ng t\u1ee9c th\xec v\xe0 \u0111\u01b0\u1ee3c l\u01b0u l\u1ea1i tr\xean thi\u1ebft b\u1ecb.",B.Q,null)
